const state={route:'home',tabs:['home','browser','files','studio'],active:'home',history:['home'],hi:0,theme:'light',bookmark:true,folder:'browser-os',file:'src/components/layout/UnifiedTabBar.vue',fileSearch:'',editorTab:'UnifiedTabBar.vue',editorText:'// BrowserOS UI 2.0 concept\nexport interface WorkspaceTab {\n  id: string;\n  kind: \'web\' | \'file\' | \'module\';\n  resourceKey: string;\n  dirty?: boolean;\n}\n\n// This is a mock document in an offline prototype.\n',dirty:false,dock:'terminal',agentModel:'Agnes 3.0 Flash',agentInput:'',agentMessages:[{role:'agent',text:'欢迎进入 Coding Agent。选择项目、浏览文件，或提交一个受控任务。'}],agentApproval:'pending',gridCount:4,gridSelected:0,toolFilter:'all',toolQuery:'',sql:'SELECT id, staff_id, nick_name, create_time FROM ali_customer LIMIT 3;',sqlRows:[],dbTab:'sql',dbSelected:'ali_customer',gitView:'history',gitFilter:'',gitSelected:0,skillStep:'overview',skillName:'我的技能',skillDescription:'',skills:['我的技能'],taskModal:false,tasks:[],taskName:'',taskSchedule:'0 * * * *',graphSelected:'BrowserOS',scriptName:'',scripts:[],clip:'这里是 BrowserOS 统一剪贴板的演示内容。',clipHistory:[],settingsSection:'appearance',termOutput:['✓ BrowserOS UI 2.0 交互设计原型','本演示无需联网，所有数据保存在当前页面。','~$ help','命令：help / ls / pwd / clear / git status / npm run check'],terminalInput:'',appNavCollapsed:false};
const sampleFiles=[{name:'src',kind:'目录',size:'—',date:'今天',path:'src'},{name:'docs',kind:'目录',size:'—',date:'今天',path:'docs'},{name:'src/components/layout/UnifiedTabBar.vue',kind:'Vue',size:'18 KB',date:'今天',path:'src/components/layout/UnifiedTabBar.vue'},{name:'src/styles/tokens.css',kind:'CSS',size:'1.3 KB',date:'今天',path:'src/styles/tokens.css'},{name:'src/capabilities/database/ui/SqlEditor.vue',kind:'Vue',size:'27 KB',date:'昨天',path:'src/capabilities/database/ui/SqlEditor.vue'},{name:'README.md',kind:'Markdown',size:'11 KB',date:'昨天',path:'README.md'},{name:'AGENTS.md',kind:'Markdown',size:'16 KB',date:'昨天',path:'AGENTS.md'},{name:'package.json',kind:'JSON',size:'5 KB',date:'今天',path:'package.json'}];
